        @if (activeChannel is not null)
        {
            <div class="message-area-header">
                <h2># @activeChannel.Name</h2>
                <p>@activeChannel.Description</p>
            </div>

            <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
                @if (isLoadingMore)
                {
                    <div class="loading-indicator">Loading older messages...</div>
                }
                @foreach (var message in messages)
                {
                    <MessageItem Message="message"
                                 ReplyCount="GetReplyCount(message.Id)"
                                 OnOpenThread="OpenThreadAsync"
                                 OnReact="HandleReactAsync" />
                }
            </div>

            <MessageInput OnSend="SendMessageAsync" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     ThreadMessages="threadMessages"
                     OnClose="CloseThread"
                     OnReply="SendThreadReplyAsync" />
    }
</div>

@code {
    private List<Services.Channel> channels = [];
    private List<Services.Message> messages = [];
    private List<Services.Message> threadMessages = [];
    private Services.Message? threadRootMessage;
    private Services.Channel? activeChannel;
    private int activeChannelId;
    private bool threadOpen;
    private bool isLoadingMore;
    private int pageSize = 50;
    private Dictionary<int, int> replyCounts = new();
    private ElementReference messageListRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannelAsync(channels[0].Id);
        }
    }

    private async Task SelectChannelAsync(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = await ChatService.GetMessagesAsync(channelId, 0, pageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        BuildReplyCounts();
        CloseThread();
    }

    private async Task SendMessageAsync(string content)
    {
        if (activeChannel is null) return;
        var message = await ChatService.SendMessageAsync(activeChannel.Id, content, null);
        messages.Add(message);
    }

    private async Task OpenThreadAsync(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;
        threadMessages = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task SendThreadReplyAsync(string content)
    {
        if (threadRootMessage is null || activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannel.Id, content, threadRootMessage.Id);
        threadMessages.Add(reply);
        // Update reply count
        if (replyCounts.ContainsKey(threadRootMessage.Id))
            replyCounts[threadRootMessage.Id]++;
        else
            replyCounts[threadRootMessage.Id] = 1;
    }

    private async Task HandleReactAsync((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh message reactions by reloading the message in the list
        var idx = messages.FindIndex(m => m.Id == reaction.MessageId);
        if (idx >= 0)
        {
            var existing = messages[idx].Reactions.FirstOrDefault(r => r.Emoji == reaction.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                messages[idx].Reactions.Add(new Services.Reaction(reaction.Emoji, ["You"]));
            }
        }
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages
        // In a real app, JS interop would detect scroll position
        // Here we provide a simplified approach
        if (!isLoadingMore && messages.Count > 0)
        {
            isLoadingMore = true;
            var olderMessages = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, pageSize);
            if (olderMessages.Count > 0)
            {
                messages.InsertRange(0, olderMessages);
                BuildReplyCounts();
            }
            isLoadingMore = false;
        }
    }

    private void BuildReplyCounts()
    {
        replyCounts.Clear();
        foreach (var msg in messages.Where(m => m.ReplyToId is not null))
        {
            var rootId = msg.ReplyToId!.Value;
            replyCounts.TryGetValue(rootId, out var count);
            replyCounts[rootId] = count + 1;
        }
    }

    private int GetReplyCount(int messageId)
    {
        return replyCounts.GetValueOrDefault(messageId);
    }
}

