toolArgs.file_text:
.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

/* Message Area */
.message-area {
    width: 55%;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
}

.message-area.expanded {
    width: 80%;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    background: #36393f;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
}

.message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #8e9297;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #8e9297;
    font-size: 0.85rem;
}

/* Thread Panel */
::deep .thread-panel {
    width: 25%;
    min-width: 250px;
    background: #2f3136;
    color: #dcddde;
    border-left: 1px solid #202225;
    display: flex;
    flex-direction: column;
}

