toolArgs.file_text:
.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
}

.thread-header h4 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
}

.close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background 0.15s;
}

.close-btn:hover {
    background: #4f545c;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    background: #36393f;
    border-bottom: 1px solid #202225;
}

.thread-root-message .message-author {
    font-weight: 600;
    font-size: 0.85rem;
    color: #fff;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    color: #b9bbbe;
    margin: 4px 0 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-reply-item {
    padding: 8px 0;
    border-bottom: 1px solid #2c2f33;
}

.thread-reply-item:last-child {
    border-bottom: none;
}

.thread-reply-item .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
}

.thread-reply-item .message-author {
    font-weight: 600;
    font-size: 0.8rem;
    color: #fff;
}

.thread-reply-item .message-time {
    font-size: 0.7rem;
    color: #72767d;
}

.thread-reply-item .message-content {
    font-size: 0.85rem;
    color: #dcddde;
}

